<script setup>import{onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{studentApi,formatTime}from'../../api/student';import{lifecycleMeta}from'../../utils/studentExamLifecycle';const route=useRoute(),router=useRouter(),exam=ref(),error=ref(''),busy=ref(false),loading=ref(true);onMounted(async()=>{try{exam.value=(await studentApi.exam(route.params.examId)).data}catch(e){error.value=e.message}finally{loading.value=false}});async function enter(){busy.value=true;error.value='';try{const p=(await studentApi.enter(exam.value.id)).data;router.push('/student/paper/'+p.submissionId)}catch(e){error.value=e.message}finally{busy.value=false}}</script>
<template><p><RouterLink to="/student">← 返回考试列表</RouterLink></p><p v-if="error" class="error-message">{{error}}</p><p v-if="loading" class="empty-state">正在加载考试详情…</p><article v-if="exam" class="surface student-exam-detail"><div class="section-head student-detail-heading"><h1>{{exam.title}}</h1><span :class="['badge',exam.lifecycleStatus]">{{lifecycleMeta(exam.lifecycleStatus).label}}</span></div><p class="preserve">{{exam.description||'暂无考试说明'}}</p><div class="meta-strip"><span>课程：{{exam.courseName}}</span><span>题目：{{exam.questionCount}} 道</span><span>考试：{{formatTime(exam.startTime)}} 至 {{formatTime(exam.endTime)}}</span><span>最早交卷：开考 {{exam.minSubmitMinutes}} 分钟后</span></div><p class="notice">首次迟到超过 {{exam.lateEntryMinutes}} 分钟将无法入场；已进入且仍在答题中的答卷可以重新进入。</p><button v-if="['AVAILABLE','IN_PROGRESS'].includes(exam.lifecycleStatus)" class="primary" :disabled="busy" @click="enter">{{busy?'正在进入…':lifecycleMeta(exam.lifecycleStatus).action}}</button><RouterLink v-else-if="exam.lifecycleStatus==='RESULTS_RELEASED'" class="primary" :to="'/student/results/'+exam.submissionId">查看成绩</RouterLink><p v-else-if="lifecycleMeta(exam.lifecycleStatus).hint">{{lifecycleMeta(exam.lifecycleStatus).hint}}</p></article></template>
